      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that voice chat can be turned off in Fortnite: Battle Royale.",
      "stance": "mitigation",
      "quote": "How do you turn off voice chat in Fortnite: Battle Royale?"
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that Fortnite encourages purchases such as upgrades to Deluxe and Super Deluxe editions, as well as in-game currency called V-Bucks that can be used to buy bonus items.",
      "stance": "risk",
      "quote": "However, even within the free-to-play version, players can spend real money. Fortnite encourages purchases such as upgrades to Deluxe and Super Deluxe editions, as well as in-game currency called V-Bucks that can be used to buy bonus items."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that accounts for users under 13 are automatically assigned a cabined account where parents must consent to in-game purchases and chatting.",
      "stance": "risk",
      "quote": "Children below that age are automatically assigned a \"cabined account,\" where parents and caregivers have to consent to their child getting access to certain features. These include in-game purchases and chatting."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that children below 13 are automatically assigned a cabined account requiring parental consent for purchases and chat.",
      "stance": "risk",
      "quote": "Children below that age are automatically assigned a \"cabined account,\" where parents and caregivers have to consent to their child getting access to certain features. These include in-game purchases and chatting."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that Fortnite: Battle Royale is loaded with violence but it is all cartoonish rather than bloody or gory.",
      "stance": "neutral",
      "quote": "Fortnite: Battle Royale is loaded with violence, but it's all cartoonish, rather than bloody or gory. Since the object is to be the last one standing, you'll constantly shoot other players and dodge fatal storms. However, there's no blood; defeated enemies simply vanish."
    },
    {
      "ref": "[D522]",
      "area": "developer_record",
      "claim": "A parent reports that Epic Games has faced regulatory scrutiny over cabined accounts and parental consent requirements.",
      "stance": "risk",
      "quote": "Children below that age are automatically assigned a \"cabined account,\" where parents and caregivers have to consent to their child getting access to certain features. These include in-game purchases and chatting. Keep in mind that the game determines a user's age based on the date of birth they enter when setting up an account."
    }
  ]
